const SETS = { en: EN, de: DE, fr: FR, ja: JA, nl: NL, it: IT, es: ES };
export function strings(lang) { return SETS[lang] || EN; }
export function fill(s, vars) { return String(s).replace(/\{(\w+)\}/g, (m, k) => (vars && vars[k] !== undefined ? vars[k] : m)); }
export const LANGS = Object.keys(SETS);
